def ui_text(language: UiLanguage | str, message: str, **values: object) -> str:
    selected = UiLanguage(language)
    text = ITALIAN_UI.get(message, message) if selected is UiLanguage.ITALIAN else message
    if selected is UiLanguage.ITALIAN and text == message:
        if message.startswith("Yahoo Inbox is accessible · ") and message.endswith(" messages"):
            count = message.removeprefix("Yahoo Inbox is accessible · ").removesuffix(" messages")
            text = f"La Posta in arrivo Yahoo è accessibile · {count} messaggi"
        elif message.startswith("local ") and message.endswith(" cache is missing or ambiguous"):
            profile = message.removeprefix("local ").removesuffix(" cache is missing or ambiguous")
            text = f"La cache locale {profile} è assente o ambigua"
        elif "; at least " in message and message.endswith(" GB RAM is recommended"):
            base, amount = message.split("; at least ", 1)
            amount = amount.removesuffix(" GB RAM is recommended")
            text = f"{ITALIAN_UI.get(base, base)}; sono consigliati almeno {amount} GB di RAM"
    return text.format(**values) if values else text
